"""Run only after a completed same-budget clock preflight; never combines prior elapsed periods."""
from pathlib import Path
import json,subprocess,datetime,argparse,re,os
p=argparse.ArgumentParser();p.add_argument('--seconds',type=int,default=300);p.add_argument('--clock-directory',default='docs/phase12/clock-stability');p.add_argument('--run-name',default='mainnet');p.add_argument('--container-name',default='mintbot-phase12-mainnet');p.add_argument('--launch-record',default='runtime-launch.json');p.add_argument('--history',default='docs/phase11/coverage-history.json,docs/phase11/phase11-coverage-history.json');p.add_argument('--output-root',default='docs/phase12');p.add_argument('--image',default='mintbot:phase12-readonly');p.add_argument('--identity-diagnostics',action='store_true');p.add_argument('--bounded-verification',action='store_true');p.add_argument('--wait',action='store_true');cfg=p.parse_args()
assert re.fullmatch(r'[A-Za-z0-9_-]{1,64}',cfg.run_name)
root=Path.cwd();out=(root/cfg.output_root).resolve();clock=Path(cfg.clock_directory).resolve();pre=json.loads((clock/'evidence.json').read_text());assert pre['stableForRequestedInterval'] and pre['actualMonotonicSeconds']>=cfg.seconds
assert not (out/cfg.launch_record).exists(),'Existing launch record preserved'
(out/'runtime').mkdir(exist_ok=True);(out/'control').mkdir(exist_ok=True)
history=[Path(p).resolve() for p in cfg.history.split(',')];historyArg=','.join('/app/history/input-'+str(i)+'.json' for i in range(len(history)))
image=subprocess.check_output(['docker','image','inspect',cfg.image,'--format','{{.Id}}'],text=True).strip()
a=['docker','run','-d','--init','--name',cfg.container_name,'--read-only','--network','host','--cap-drop','ALL','--security-opt','no-new-privileges','--mount',f'type=bind,source={out}/runtime,target=/app/data','--mount',f'type=bind,source={out}/control,target=/app/control','--mount',f'type=bind,source={clock},target=/app/host-health,readonly',*[item for i,p in enumerate(history) for item in ['--mount',f'type=bind,source={p},target=/app/history/input-{i}.json,readonly']],*[item for key in ['SOLANA_RPC_URL','SOLANA_WS_URL','SOLANA_SECONDARY_RPC_URL','SOLANA_SECONDARY_WS_URL'] if key in os.environ for item in ['-e',key]],*(['-e','RESEARCH_IDENTITY_DIAGNOSTICS=true'] if cfg.identity_diagnostics else []),*(['-e','RESEARCH_BOUNDED_VERIFICATION=true'] if cfg.bounded_verification else []),'-e','MODE=paper','-e','RESEARCH_STOP_PATH=/app/control/global-stop.json','-e','RESEARCH_OWNER_PATH=/app/control/owner.lock','-e','RESEARCH_REQUIRE_HOST_HEALTH=true','-e','RESEARCH_HOST_HEALTH_PATH=/app/host-health/evidence.json','--health-cmd',f"node -e \"try{{const p=JSON.parse(require('fs').readFileSync('/app/data/{cfg.run_name}/run-progress.json'));process.exit(Date.now()-p.updatedAt<15000&&p.supervisor.liveReady&&!p.pipeline.fatal&&!p.journal.writerFailure&&p.journal.quarantined===0&&p.journal.gaps.every(g=>g.status==='recovered')&&p.coverageEpoch.researchPolicyReview==='verified'?0:1)}}catch{{process.exit(1)}}\"",'--health-interval','15s','--health-timeout','3s','--health-retries','2',image,'node','dist/scripts/phase11-mainnet.js','--run','--seconds',str(cfg.seconds),'--max-candidates','120','--history-evidence',historyArg,'--output',f'/app/data/{cfg.run_name}']
r=subprocess.run(a,capture_output=True,text=True);assert r.returncode==0,r.stderr
(out/cfg.launch_record).write_text(json.dumps({'launchedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'args':a,'container':r.stdout.strip(),'image':image,'clockPreflight':str(clock/'evidence.json'),'independentPolicyReview':'unmet','requestedSeconds':cfg.seconds,'scope':'Fresh bounded four-venue run after at-least-equal timing preflight; prior periods never added.'},indent=2)+'\n');print(r.stdout.strip())

if cfg.wait:
 result=subprocess.run(['docker','wait',cfg.container_name],capture_output=True,text=True,timeout=cfg.seconds+180)
 exitCode=int(result.stdout.strip()) if result.returncode==0 and result.stdout.strip().isdigit() else -1
 (out/(Path(cfg.launch_record).stem+'-exit.json')).write_text(json.dumps({'dockerWaitExitCode':result.returncode,'containerExitCode':exitCode,'finishedAt':datetime.datetime.now(datetime.timezone.utc).isoformat()},indent=2)+'\n')
 raise SystemExit(0 if exitCode==0 else 2)
